"""Package the encrypted owner script as a self-contained local HTML viewer.
The opening key is deliberately absent from the public archive.
"""
from pathlib import Path
import json, zipfile
root=Path(__file__).resolve().parents[1]
version='2.9.21'
value=json.loads((root/f'schools/owner-script-{version}.encrypted.json').read_text())
html='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سكربت راصد — خاص بالمالك</title><style>body{max-width:960px;margin:25px auto;padding:16px;background:#edf4f7;color:#173c4b;font:15px/1.8 Tahoma,Arial}section{background:white;padding:20px;border-radius:14px}input,button,textarea{box-sizing:border-box;font:inherit;padding:10px;border:1px solid #b8ced8;border-radius:7px}input,textarea{width:100%}button{background:#1767ae;color:white;cursor:pointer;margin:10px 0}textarea{height:55vh;direction:ltr;text-align:left;font:12px monospace}[hidden]{display:none!important}</style><h1>سكربت راصد المدارس — VERSION</h1><p>خاص بمالك راصد. هذا الملف يعمل من جهازك دون الاتصال بموقع راصد.</p><section><form id="unlock"><label>الصق مفتاح الفتح الموجود في المحادثة<input id="key" type="password" autocomplete="off" spellcheck="false" dir="ltr" required></label><button type="submit">فتح السكربت</button></form><p id="state" role="status">الملف مشفر؛ يلزم مفتاح الفتح الخاص به.</p><div id="actions" hidden><button id="copy" type="button">نسخ السكربت كاملًا</button><p>استبدل السكربت في مشروع المدارس الحالي، ثم احفظه وحدّث النشر الحالي بإصدار جديد. أبقِ رابط النشر وخصائص المشروع كما هي.</p><textarea id="code" readonly aria-label="السكريبت كاملًا"></textarea></div></section><script id="encrypted" type="application/json">CIPHER</script><script>
const form=document.getElementById('unlock'),status=document.getElementById('state'),area=document.getElementById('code');
form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{const opening=document.getElementById('key').value.trim();if(!/^[A-Za-z0-9_-]{43}$/.test(opening))throw Error('الصق مفتاح الفتح كاملًا من المحادثة.');if(!globalThis.crypto?.subtle)throw Error('افتح هذا الملف في Chrome أو Edge على الكمبيوتر.');const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0)),key=await crypto.subtle.importKey('raw',bytes(opening.replace(/-/g,'+').replace(/_/g,'/')+'='),'AES-GCM',false,['decrypt']),value=JSON.parse(document.getElementById('encrypted').textContent),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(value.nonce)},key,bytes(value.data)),text=new TextDecoder().decode(plain);if(!text.trimEnd().endsWith('// END MIRSAD SCHOOLS COMPLETE SCRIPT VERSION'))throw Error('الملف غير مكتمل.');area.value=text;document.getElementById('key').value='';form.hidden=true;document.getElementById('actions').hidden=false;status.textContent='السكربت كامل وجاهز للنسخ.'}catch(error){status.textContent=error.name==='OperationError'?'مفتاح الفتح غير صحيح؛ انسخه كاملًا من المحادثة.':error.message}finally{button.disabled=false}};
document.getElementById('copy').onclick=async()=>{try{await navigator.clipboard.writeText(area.value);status.textContent='تم نسخ السكربت كاملًا.'}catch{area.focus();area.select();status.textContent='تم تحديد السكربت كاملًا؛ اضغط Ctrl+C لنسخه.'}};
</script></html>'''.replace('VERSION',version).replace('CIPHER',json.dumps(value))
out=root/f'schools/downloads/Rased-Schools-Owner-Script-{version}.zip'
with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
 z.writestr('افتح السكربت.html',html.encode('utf-8'))
 z.writestr('اقرأ أولاً.txt',('فك الضغط، وافتح ملف «افتح السكربت.html» في كروم أو إيدج، ثم الصق مفتاح الفتح من المحادثة.\nلا ترسل مفتاح الفتح للمدارس. هذه حزمة السكربت الخاصة بالمالك.\nبعد النسخ، استبدل سكربت مشروع المدارس الحالي واحفظه، ثم نشر ← إدارة عمليات النشر ← تعديل ← إصدار جديد ← نشر. أبقِ رابط النشر نفسه.\n').encode('utf-8-sig'))
print('Packaged encrypted offline owner viewer; no opening key included.')
